package contracts

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"regexp"
	"slices"

	reasoningv1 "github.com/Standard-Syntax/basic/go/gen/harness/reasoning/v1"
)

const emptySHA256 = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"

var commitPattern = regexp.MustCompile(`^[0-9a-f]{40}$`)

type ImplementationRequest struct {
	Envelope                    Envelope
	ApprovedTaskID              string
	ApprovedTaskDigest          string
	ApprovedSpecificationID     string
	ApprovedSpecificationDigest string
	BaseCommit                  string
	ReadablePaths               []string
	WritablePaths               []string
	ProhibitedPaths             []string
	AcceptanceCriterionIDs      []string
	AvailableCheckIDs           []string
	RepositoryContext           []RepositoryContextFile
}

type RepositoryContextFile struct {
	Path    string
	SHA256  string
	Content string
}

type FileOperation string

const (
	FileCreate FileOperation = "create"
	FileUpdate FileOperation = "update"
	FileDelete FileOperation = "delete"
)

type FileChange struct {
	Path                   string
	Operation              FileOperation
	ExpectedOriginalSHA256 string
	ReplacementContent     *string
	Rationale              string
	AcceptanceCriterionIDs []string
}

type ImplementationProposal struct {
	Summary                   string
	Changes                   []FileChange
	RequestedDeclaredCheckIDs []string
	Assumptions               []string
	UnresolvedQuestions       []string
	ScopeChangeRequest        *ScopeChangeRequest
}

type ScopeChangeRequest struct {
	Summary                         string
	RequestedReadablePaths          []string
	RequestedWritablePaths          []string
	RequestedAcceptanceCriterionIDs []string
	RequestedCheckIDs               []string
}

type ImplementationReasoner interface {
	ProposeImplementation(context.Context, ImplementationRequest) (ImplementationProposal, error)
}

func MapImplementationRequest(value *reasoningv1.ImplementationRequest) (ImplementationRequest, error) {
	if value == nil {
		return ImplementationRequest{}, errors.New("implementation request is required")
	}
	envelope, err := MapEnvelope(value.GetEnvelope(), StageImplementation)
	if err != nil {
		return ImplementationRequest{}, err
	}
	if err := validateImplementationRequestFields(value); err != nil {
		return ImplementationRequest{}, err
	}
	if err := validatePathScopes(
		value.GetReadablePaths(), value.GetWritablePaths(), value.GetProhibitedPaths(),
	); err != nil {
		return ImplementationRequest{}, err
	}
	if err := validateAvailableChecks(value.GetAvailableCheckIds()); err != nil {
		return ImplementationRequest{}, err
	}
	repositoryContext, err := mapRepositoryContext(value, envelope.InputArtifacts)
	if err != nil {
		return ImplementationRequest{}, err
	}
	return ImplementationRequest{
		Envelope:                    envelope,
		ApprovedTaskID:              value.GetApprovedTaskId(),
		ApprovedTaskDigest:          value.GetApprovedTaskDigest(),
		ApprovedSpecificationID:     value.GetApprovedSpecificationId(),
		ApprovedSpecificationDigest: value.GetApprovedSpecificationDigest(),
		BaseCommit:                  value.GetBaseCommit(),
		ReadablePaths:               value.GetReadablePaths(), WritablePaths: value.GetWritablePaths(),
		ProhibitedPaths:        value.GetProhibitedPaths(),
		AcceptanceCriterionIDs: value.GetAcceptanceCriterionIds(),
		AvailableCheckIDs:      value.GetAvailableCheckIds(),
		RepositoryContext:      repositoryContext,
	}, nil
}

func validateImplementationRequestFields(value *reasoningv1.ImplementationRequest) error {
	if !taskIDPattern.MatchString(value.GetApprovedTaskId()) ||
		!digestPattern.MatchString(value.GetApprovedTaskDigest()) ||
		value.GetApprovedSpecificationId() == "" ||
		!digestPattern.MatchString(value.GetApprovedSpecificationDigest()) ||
		!commitPattern.MatchString(value.GetBaseCommit()) ||
		!validCriteria(value.GetAcceptanceCriterionIds()) ||
		len(value.GetAvailableCheckIds()) == 0 {
		return errors.New("invalid implementation request identity or limits")
	}
	return nil
}

func validateAvailableChecks(values []string) error {
	for _, check := range values {
		if !checkIDPattern.MatchString(check) {
			return errors.New("invalid available check ID")
		}
	}
	return nil
}

func mapRepositoryContext(
	value *reasoningv1.ImplementationRequest, artifacts []Artifact,
) ([]RepositoryContextFile, error) {
	repositoryContext := make([]RepositoryContextFile, 0, len(value.GetRepositoryContext()))
	for _, file := range value.GetRepositoryContext() {
		mapped, err := mapRepositoryContextFile(file, value, artifacts)
		if err != nil {
			return nil, err
		}
		repositoryContext = append(repositoryContext, mapped)
	}
	return repositoryContext, nil
}

func mapRepositoryContextFile(
	file *reasoningv1.RepositoryContextFile,
	request *reasoningv1.ImplementationRequest,
	artifacts []Artifact,
) (RepositoryContextFile, error) {
	if !validRepoPath(file.GetPath()) || !pathWithin(file.GetPath(), request.GetReadablePaths()) ||
		!digestPattern.MatchString(file.GetSha256()) {
		return RepositoryContextFile{}, errors.New("invalid repository context")
	}
	if pathIsProhibited(file.GetPath(), request.GetProhibitedPaths()) {
		return RepositoryContextFile{}, errors.New("repository context targets prohibited path")
	}
	sum := sha256.Sum256([]byte(file.GetContent()))
	if hex.EncodeToString(sum[:]) != file.GetSha256() {
		return RepositoryContextFile{}, errors.New("repository context digest mismatch")
	}
	if !artifactContainsDigest(artifacts, file.GetSha256()) {
		return RepositoryContextFile{}, errors.New(
			"repository context is not bound to an input artifact",
		)
	}
	return RepositoryContextFile{
		Path: file.GetPath(), SHA256: file.GetSha256(), Content: file.GetContent(),
	}, nil
}

func pathIsProhibited(filePath string, prohibitedPaths []string) bool {
	for _, prohibited := range prohibitedPaths {
		if pathWithin(filePath, []string{prohibited}) {
			return true
		}
	}
	return false
}

func artifactContainsDigest(artifacts []Artifact, digest string) bool {
	for _, artifact := range artifacts {
		if artifact.SHA256 == digest {
			return true
		}
	}
	return false
}

func MapImplementationProposal(
	value *reasoningv1.ImplementationProposal, request ImplementationRequest,
) (ImplementationProposal, error) {
	if value == nil || value.GetIdentity() == nil {
		return ImplementationProposal{}, errors.New("implementation proposal identity is required")
	}
	if err := validateProposalIdentity(value.GetIdentity(), request.Envelope, StageImplementation); err != nil {
		return ImplementationProposal{}, err
	}
	if value.GetApprovedTaskId() != request.ApprovedTaskID ||
		value.GetApprovedTaskDigest() != request.ApprovedTaskDigest ||
		value.GetApprovedSpecificationDigest() != request.ApprovedSpecificationDigest {
		return ImplementationProposal{}, errors.New("implementation request identity mismatch")
	}
	if value.GetSummary() == "" || len(value.GetChanges()) == 0 {
		return ImplementationProposal{}, errors.New("incomplete implementation proposal")
	}
	if err := validateRequestedChecks(value.GetRequestedDeclaredCheckIds(), request); err != nil {
		return ImplementationProposal{}, err
	}
	changes, covered, err := mapFileChanges(value.GetChanges(), request)
	if err != nil {
		return ImplementationProposal{}, err
	}
	if err := validateImplementationCoverage(request.AcceptanceCriterionIDs, covered); err != nil {
		return ImplementationProposal{}, err
	}
	scopeChange, err := mapScopeChangeRequest(value.GetScopeChangeRequest())
	if err != nil {
		return ImplementationProposal{}, err
	}
	return ImplementationProposal{
		Summary: value.GetSummary(), Changes: changes,
		RequestedDeclaredCheckIDs: value.GetRequestedDeclaredCheckIds(),
		Assumptions:               value.GetAssumptions(), UnresolvedQuestions: value.GetUnresolvedQuestions(),
		ScopeChangeRequest: scopeChange,
	}, nil
}

func validateRequestedChecks(values []string, request ImplementationRequest) error {
	for _, check := range values {
		if !slices.Contains(request.AvailableCheckIDs, check) {
			return errors.New("undeclared check requested")
		}
	}
	return nil
}

func mapFileChanges(
	values []*reasoningv1.FileChange, request ImplementationRequest,
) ([]FileChange, map[string]bool, error) {
	covered := make(map[string]bool, len(request.AcceptanceCriterionIDs))
	changes := make([]FileChange, 0, len(values))
	for _, change := range values {
		mapped, err := mapFileChange(change, request, covered)
		if err != nil {
			return nil, nil, err
		}
		changes = append(changes, mapped)
	}
	return changes, covered, nil
}

func mapFileChange(
	change *reasoningv1.FileChange,
	request ImplementationRequest,
	covered map[string]bool,
) (FileChange, error) {
	if !validRepoPath(change.GetPath()) || !pathWithin(change.GetPath(), request.WritablePaths) ||
		change.GetRationale() == "" || len(change.GetAcceptanceCriterionIds()) == 0 {
		return FileChange{}, errors.New("invalid or out-of-scope file change")
	}
	if pathIsProhibited(change.GetPath(), request.ProhibitedPaths) {
		return FileChange{}, errors.New("file change targets prohibited path")
	}
	operation, err := validateFileOperation(change)
	if err != nil {
		return FileChange{}, err
	}
	for _, criterion := range change.GetAcceptanceCriterionIds() {
		if !slices.Contains(request.AcceptanceCriterionIDs, criterion) {
			return FileChange{}, errors.New("unknown acceptance criterion coverage")
		}
		covered[criterion] = true
	}
	return FileChange{
		Path: change.GetPath(), Operation: operation,
		ExpectedOriginalSHA256: change.GetExpectedOriginalSha256(),
		ReplacementContent:     change.ReplacementContent, Rationale: change.GetRationale(),
		AcceptanceCriterionIDs: change.GetAcceptanceCriterionIds(),
	}, nil
}

func validateImplementationCoverage(criteria []string, covered map[string]bool) error {
	for _, criterion := range criteria {
		if !covered[criterion] {
			return errors.New("required acceptance coverage missing")
		}
	}
	return nil
}

func mapScopeChangeRequest(value *reasoningv1.ScopeChangeRequest) (*ScopeChangeRequest, error) {
	if value == nil {
		return nil, nil
	}
	if value.GetSummary() == "" {
		return nil, errors.New("scope change summary is required")
	}
	for _, paths := range [][]string{
		value.GetRequestedReadablePaths(), value.GetRequestedWritablePaths(),
	} {
		for _, requestedPath := range paths {
			if !validRepoPath(requestedPath) {
				return nil, errors.New("invalid scope change path")
			}
		}
	}
	if len(value.GetRequestedAcceptanceCriterionIds()) > 0 &&
		!validCriteria(value.GetRequestedAcceptanceCriterionIds()) {
		return nil, errors.New("invalid scope change acceptance criterion")
	}
	for _, check := range value.GetRequestedCheckIds() {
		if !checkIDPattern.MatchString(check) {
			return nil, errors.New("invalid scope change check")
		}
	}
	return &ScopeChangeRequest{
		Summary:                         value.GetSummary(),
		RequestedReadablePaths:          value.GetRequestedReadablePaths(),
		RequestedWritablePaths:          value.GetRequestedWritablePaths(),
		RequestedAcceptanceCriterionIDs: value.GetRequestedAcceptanceCriterionIds(),
		RequestedCheckIDs:               value.GetRequestedCheckIds(),
	}, nil
}

func validateFileOperation(change *reasoningv1.FileChange) (FileOperation, error) {
	switch change.GetOperation() {
	case reasoningv1.FileOperation_FILE_OPERATION_CREATE:
		if change.GetExpectedOriginalSha256() != emptySHA256 || change.ReplacementContent == nil {
			return "", errors.New("create requires empty-content digest and replacement content")
		}
		return FileCreate, nil
	case reasoningv1.FileOperation_FILE_OPERATION_UPDATE:
		if !digestPattern.MatchString(change.GetExpectedOriginalSha256()) ||
			change.ReplacementContent == nil {
			return "", errors.New("update requires digest and replacement content")
		}
		return FileUpdate, nil
	case reasoningv1.FileOperation_FILE_OPERATION_DELETE:
		if !digestPattern.MatchString(change.GetExpectedOriginalSha256()) ||
			change.ReplacementContent != nil {
			return "", errors.New("delete requires digest and no replacement content")
		}
		return FileDelete, nil
	default:
		return "", errors.New("unsupported file operation")
	}
}
// Package contracts maps untrusted Protobuf transports into validated domain values.
package contracts

import (
	"errors"
	"fmt"
	"regexp"
	"time"

	reasoningv1 "github.com/Standard-Syntax/basic/go/gen/harness/reasoning/v1"
)

var digestPattern = regexp.MustCompile(`^[0-9a-f]{64}$`)

type Stage string

const (
	StageSpecification  Stage = "specification"
	StagePlanning       Stage = "planning"
	StageImplementation Stage = "implementation"
	StageReview         Stage = "review"
)

type Envelope struct {
	SchemaVersion       string
	RequestID           string
	RunID               string
	TaskID              *string
	Stage               Stage
	Attempt             uint32
	CreatedAt           time.Time
	ExpiresAt           time.Time
	MaximumInputTokens  uint64
	MaximumOutputTokens uint64
	MaximumRequests     uint32
	InputArtifacts      []Artifact
	AgentManifestDigest string
}

type Artifact struct {
	URI    string
	SHA256 string
}

func MapEnvelope(value *reasoningv1.ReasoningRequestEnvelope, expected Stage) (Envelope, error) {
	if value == nil {
		return Envelope{}, errors.New("envelope is required")
	}
	stage, err := validateEnvelopeHeader(value, expected)
	if err != nil {
		return Envelope{}, err
	}
	created, expires, err := mapEnvelopeTimes(value)
	if err != nil {
		return Envelope{}, err
	}
	if err := validateEnvelopeBudget(value); err != nil {
		return Envelope{}, err
	}
	if !digestPattern.MatchString(value.GetAgentManifestDigest()) {
		return Envelope{}, errors.New("invalid agent manifest digest")
	}
	artifacts, err := mapArtifacts(value.GetInputArtifacts())
	if err != nil {
		return Envelope{}, err
	}
	return Envelope{
		SchemaVersion:       value.GetSchemaVersion(),
		RequestID:           value.GetRequestId(),
		RunID:               value.GetRunId(),
		TaskID:              value.TaskId,
		Stage:               stage,
		Attempt:             value.GetAttempt(),
		CreatedAt:           created,
		ExpiresAt:           expires,
		MaximumInputTokens:  value.GetBudget().GetMaximumInputTokens(),
		MaximumOutputTokens: value.GetBudget().GetMaximumOutputTokens(),
		MaximumRequests:     value.GetBudget().GetMaximumProviderRequests(),
		InputArtifacts:      artifacts,
		AgentManifestDigest: value.GetAgentManifestDigest(),
	}, nil
}

func validateEnvelopeHeader(
	value *reasoningv1.ReasoningRequestEnvelope, expected Stage,
) (Stage, error) {
	stage, err := mapStage(value.GetStage())
	if err != nil || stage != expected {
		return "", errors.New("unexpected reasoning stage")
	}
	if err := validateAuthority(value.GetAuthority()); err != nil {
		return "", err
	}
	if value.GetSchemaVersion() != "1" || value.GetRequestId() == "" || value.GetRunId() == "" {
		return "", errors.New("invalid envelope identity")
	}
	return stage, nil
}

func mapEnvelopeTimes(value *reasoningv1.ReasoningRequestEnvelope) (time.Time, time.Time, error) {
	if value.GetAttempt() == 0 || value.GetCreatedAt() == nil || value.GetExpiresAt() == nil {
		return time.Time{}, time.Time{}, errors.New("invalid attempt or timestamps")
	}
	if err := value.GetCreatedAt().CheckValid(); err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("created_at: %w", err)
	}
	if err := value.GetExpiresAt().CheckValid(); err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("expires_at: %w", err)
	}
	created := value.GetCreatedAt().AsTime()
	expires := value.GetExpiresAt().AsTime()
	if !expires.After(created) {
		return time.Time{}, time.Time{}, errors.New("expires_at must follow created_at")
	}
	return created, expires, nil
}

func validateEnvelopeBudget(value *reasoningv1.ReasoningRequestEnvelope) error {
	if value.GetBudget() == nil || value.GetBudget().GetMaximumInputTokens() == 0 ||
		value.GetBudget().GetMaximumOutputTokens() == 0 ||
		value.GetBudget().GetMaximumProviderRequests() == 0 {
		return errors.New("positive reasoning budget is required")
	}
	return nil
}

func mapArtifacts(values []*reasoningv1.ArtifactDigest) ([]Artifact, error) {
	artifacts := make([]Artifact, 0, len(values))
	for _, artifact := range values {
		if !digestPattern.MatchString(artifact.GetSha256()) ||
			artifact.GetArtifactUri() != "artifact://sha256/"+artifact.GetSha256() {
			return nil, errors.New("invalid input artifact")
		}
		artifacts = append(artifacts, Artifact{URI: artifact.GetArtifactUri(), SHA256: artifact.GetSha256()})
	}
	return artifacts, nil
}

func validateAuthority(value *reasoningv1.AuthorityConstraints) error {
	if value == nil || value.GetMode() != reasoningv1.AuthorityMode_AUTHORITY_MODE_PROPOSAL_ONLY ||
		value.GetMayMutateKernelState() || value.GetMayExecuteCommands() ||
		value.GetMayModifyFiles() || value.GetMayExpandScope() || value.GetMayApproveWork() {
		return errors.New("authority violation: proposal_only with all capabilities false is required")
	}
	return nil
}

func mapStage(value reasoningv1.ReasoningStage) (Stage, error) {
	switch value {
	case reasoningv1.ReasoningStage_REASONING_STAGE_SPECIFICATION:
		return StageSpecification, nil
	case reasoningv1.ReasoningStage_REASONING_STAGE_PLANNING:
		return StagePlanning, nil
	case reasoningv1.ReasoningStage_REASONING_STAGE_IMPLEMENTATION:
		return StageImplementation, nil
	case reasoningv1.ReasoningStage_REASONING_STAGE_REVIEW:
		return StageReview, nil
	default:
		return "", errors.New("unknown reasoning stage")
	}
}

func validateProposalIdentity(
	value *reasoningv1.ProposalIdentity, request Envelope, expected Stage,
) error {
	stage, err := mapStage(value.GetStage())
	if err != nil || stage != expected || value.GetSchemaVersion() != request.SchemaVersion ||
		value.GetRequestId() != request.RequestID || value.GetRunId() != request.RunID ||
		value.GetAttempt() != request.Attempt ||
		value.GetAgentManifestDigest() != request.AgentManifestDigest {
		return errors.New("proposal request identity mismatch")
	}
	if (value.TaskId == nil) != (request.TaskID == nil) ||
		(value.TaskId != nil && *value.TaskId != *request.TaskID) ||
		len(value.GetInputArtifactDigests()) != len(request.InputArtifacts) {
		return errors.New("proposal request identity mismatch")
	}
	for index, artifact := range request.InputArtifacts {
		if value.GetInputArtifactDigests()[index] != artifact.SHA256 {
			return errors.New("proposal request identity mismatch")
		}
	}
	return nil
}
package contracts

import (
	"bytes"
	"os"
	"path/filepath"
	"runtime"
	"testing"

	reasoningv1 "github.com/Standard-Syntax/basic/go/gen/harness/reasoning/v1"
	"google.golang.org/protobuf/proto"
)

func implementationFixture(t *testing.T, name string) []byte {
	t.Helper()
	_, source, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("locate test source")
	}
	path := filepath.Join(
		filepath.Dir(source), "..", "..", "..", "..", "tests", "contracts", "v1",
		"implementation", name,
	)
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func validImplementation(
	t *testing.T,
) (ImplementationRequest, *reasoningv1.ImplementationProposal) {
	t.Helper()
	var requestPB reasoningv1.ImplementationRequest
	if err := proto.Unmarshal(implementationFixture(t, "request.bin"), &requestPB); err != nil {
		t.Fatal(err)
	}
	request, err := MapImplementationRequest(&requestPB)
	if err != nil {
		t.Fatal(err)
	}
	var proposal reasoningv1.ImplementationProposal
	if err := proto.Unmarshal(implementationFixture(t, "proposal.bin"), &proposal); err != nil {
		t.Fatal(err)
	}
	return request, &proposal
}

func TestImplementationOperationsMapAndRoundTrip(t *testing.T) {
	request, proposal := validImplementation(t)
	if len(request.RepositoryContext) != 1 {
		t.Fatal("repository context was discarded")
	}
	mapped, err := MapImplementationProposal(proposal, request)
	if err != nil {
		t.Fatal(err)
	}
	want := []FileOperation{FileCreate, FileUpdate, FileDelete}
	for index, operation := range want {
		if mapped.Changes[index].Operation != operation {
			t.Fatalf("operation %d = %s", index, mapped.Changes[index].Operation)
		}
	}
	encoded, err := proto.MarshalOptions{Deterministic: true}.Marshal(proposal)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(encoded, implementationFixture(t, "proposal.bin")) {
		t.Fatal("Go deterministic serialization differs from Python fixture")
	}
}

func TestScopeChangeRequestIsPreservedButNotApplied(t *testing.T) {
	request, proposal := validImplementation(t)
	proposal.ScopeChangeRequest = &reasoningv1.ScopeChangeRequest{
		Summary:                         "Need a wider read scope.",
		RequestedReadablePaths:          []string{"docs"},
		RequestedAcceptanceCriterionIds: []string{"AC-004"},
		RequestedCheckIds:               []string{"CHECK-DOCS"},
	}
	mapped, err := MapImplementationProposal(proposal, request)
	if err != nil {
		t.Fatal(err)
	}
	if mapped.ScopeChangeRequest == nil || mapped.ScopeChangeRequest.Summary == "" {
		t.Fatal("scope change request was discarded")
	}
	if len(request.ReadablePaths) != 1 || request.ReadablePaths[0] != "go" {
		t.Fatal("scope change request mutated kernel-selected scope")
	}
}

func TestInvalidImplementationProposalsFailWithoutPartialResult(t *testing.T) {
	tests := map[string]func(*reasoningv1.ImplementationProposal){
		"absolute path": func(value *reasoningv1.ImplementationProposal) {
			value.Changes[0].Path = "/etc/passwd"
		},
		"path traversal": func(value *reasoningv1.ImplementationProposal) {
			value.Changes[0].Path = "../escape"
		},
		"malformed digest": func(value *reasoningv1.ImplementationProposal) {
			value.Changes[1].ExpectedOriginalSha256 = "bad"
		},
		"request mismatch": func(value *reasoningv1.ImplementationProposal) {
			value.Identity.RequestId = "stale"
		},
		"task mismatch": func(value *reasoningv1.ImplementationProposal) {
			value.Identity.TaskId = proto.String("TASK-999")
		},
		"incomplete coverage": func(value *reasoningv1.ImplementationProposal) {
			value.Changes = value.Changes[:2]
		},
		"undeclared check": func(value *reasoningv1.ImplementationProposal) {
			value.RequestedDeclaredCheckIds = []string{"CHECK-DEPLOY"}
		},
	}
	for name, mutate := range tests {
		t.Run(name, func(t *testing.T) {
			request, proposal := validImplementation(t)
			mutate(proposal)
			mapped, err := MapImplementationProposal(proposal, request)
			if err == nil {
				t.Fatal("invalid proposal accepted")
			}
			if len(mapped.Changes) != 0 {
				t.Fatal("partial result returned")
			}
		})
	}
}

func TestAllStableRejectionCodesRoundTripInGo(t *testing.T) {
	codes := []reasoningv1.RejectionCode{
		reasoningv1.RejectionCode_REJECTION_CODE_SCHEMA_INVALID,
		reasoningv1.RejectionCode_REJECTION_CODE_REQUEST_MISMATCH,
		reasoningv1.RejectionCode_REJECTION_CODE_AUTHORITY_VIOLATION,
		reasoningv1.RejectionCode_REJECTION_CODE_SCOPE_VIOLATION,
		reasoningv1.RejectionCode_REJECTION_CODE_REQUIRED_COVERAGE_MISSING,
	}
	for _, code := range codes {
		value := &reasoningv1.ProposalRejection{
			Code: code, Summary: "deterministic rejection", RequestId: "request-impl-001",
			RunId: "run-001", TaskId: proto.String("TASK-001"), Attempt: 1,
		}
		data, err := proto.Marshal(value)
		if err != nil {
			t.Fatal(err)
		}
		var decoded reasoningv1.ProposalRejection
		if err := proto.Unmarshal(data, &decoded); err != nil {
			t.Fatal(err)
		}
		if decoded.GetCode() != code {
			t.Fatalf("code = %v; want %v", decoded.GetCode(), code)
		}
	}
}

func TestImplementationRequestRejectsUntrustedRepositoryContext(t *testing.T) {
	var request reasoningv1.ImplementationRequest
	if err := proto.Unmarshal(implementationFixture(t, "request.bin"), &request); err != nil {
		t.Fatal(err)
	}
	request.RepositoryContext[0].Content = "tampered"
	if _, err := MapImplementationRequest(&request); err == nil {
		t.Fatal("repository context digest mismatch accepted")
	}
	if err := proto.Unmarshal(implementationFixture(t, "request.bin"), &request); err != nil {
		t.Fatal(err)
	}
	request.RepositoryContext[0].Path = "go/gen/secret.go"
	if _, err := MapImplementationRequest(&request); err == nil {
		t.Fatal("prohibited repository context accepted")
	}
	if err := proto.Unmarshal(implementationFixture(t, "request.bin"), &request); err != nil {
		t.Fatal(err)
	}
	request.Envelope.InputArtifacts = request.Envelope.InputArtifacts[:1]
	if _, err := MapImplementationRequest(&request); err == nil {
		t.Fatal("repository context without envelope artifact binding accepted")
	}
}
