// Package registry stores immutable, canonical agent manifests.
package registry

import (
	"bytes"
	"context"
	"embed"
	"errors"
	"fmt"
	"regexp"
	"time"

	"github.com/Standard-Syntax/basic/go/internal/manifest"
	"github.com/Standard-Syntax/basic/go/internal/migration"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

var (
	ErrInvalidArgument = errors.New("invalid registry argument")
	ErrInvalidManifest = errors.New("invalid agent manifest")
	ErrVersionConflict = errors.New("agent version conflict")
	ErrNotFound        = errors.New("agent registration not found")
	ErrCorruptData     = errors.New("corrupt persisted agent registration")
)

var (
	validName    = regexp.MustCompile(`^[a-z][a-z0-9-]{0,62}$`)
	validVersion = regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+$`)
	validDigest  = regexp.MustCompile(`^[0-9a-f]{64}$`)
)

//go:embed migrations/*.sql
var migrationFiles embed.FS

type Registry struct {
	pool *pgxpool.Pool
}

type Record struct {
	Manifest      manifest.Manifest
	CanonicalJSON []byte
	Digest        string
	RegisteredAt  time.Time
}

type RegisterResult struct {
	Record
	Created bool
}

func New(pool *pgxpool.Pool) *Registry {
	return &Registry{pool: pool}
}

func Migrate(ctx context.Context, connectionString string) error {
	return migration.Apply(ctx, connectionString, migrationFiles, "migrations")
}

func (r *Registry) Register(ctx context.Context, rawManifest []byte) (RegisterResult, error) {
	value, canonical, digest, err := manifest.Read(rawManifest)
	if err != nil {
		return RegisterResult{}, fmt.Errorf("%w: %v", ErrInvalidManifest, err)
	}
	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return RegisterResult{}, fmt.Errorf("begin registration: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	if _, err := tx.Exec(ctx, `SELECT pg_advisory_xact_lock(
		hashtextextended($1 || ':' || $2, 719043625421948938))`,
		value.Agent.Name, value.Agent.Version); err != nil {
		return RegisterResult{}, fmt.Errorf("lock agent version: %w", err)
	}

	var record Record
	var storedName, storedVersion string
	err = tx.QueryRow(ctx, `SELECT
			agent_name,agent_version,manifest_digest,canonical_manifest,registered_at
		FROM agent_registrations WHERE agent_name=$1 AND agent_version=$2`,
		value.Agent.Name, value.Agent.Version,
	).Scan(
		&storedName, &storedVersion, &record.Digest,
		&record.CanonicalJSON, &record.RegisteredAt,
	)
	if err == nil {
		if record.Digest != digest {
			return RegisterResult{}, ErrVersionConflict
		}
		record, err = validateRecord(record, storedName, storedVersion)
		if err != nil {
			return RegisterResult{}, err
		}
		if err := tx.Commit(ctx); err != nil {
			return RegisterResult{}, fmt.Errorf("commit registration replay: %w", err)
		}
		return RegisterResult{Record: record, Created: false}, nil
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		return RegisterResult{}, fmt.Errorf("read agent version: %w", err)
	}

	record = Record{
		Manifest: value, CanonicalJSON: append([]byte(nil), canonical...), Digest: digest,
	}
	err = tx.QueryRow(ctx, `INSERT INTO agent_registrations
			(agent_name,agent_version,manifest_digest,canonical_manifest)
		VALUES($1,$2,$3,$4) RETURNING registered_at`,
		value.Agent.Name, value.Agent.Version, digest, canonical,
	).Scan(&record.RegisteredAt)
	if err != nil {
		return RegisterResult{}, fmt.Errorf("insert registration: %w", err)
	}
	if err := tx.Commit(ctx); err != nil {
		return RegisterResult{}, fmt.Errorf("commit registration: %w", err)
	}
	return RegisterResult{Record: record, Created: true}, nil
}

func (r *Registry) Get(ctx context.Context, name, version string) (Record, error) {
	if !validName.MatchString(name) || !validVersion.MatchString(version) {
		return Record{}, ErrInvalidArgument
	}
	var record Record
	var storedName, storedVersion string
	err := r.pool.QueryRow(ctx, `SELECT
			agent_name,agent_version,manifest_digest,canonical_manifest,registered_at
		FROM agent_registrations WHERE agent_name=$1 AND agent_version=$2`,
		name, version,
	).Scan(
		&storedName, &storedVersion, &record.Digest,
		&record.CanonicalJSON, &record.RegisteredAt,
	)
	if errors.Is(err, pgx.ErrNoRows) {
		return Record{}, ErrNotFound
	}
	if err != nil {
		return Record{}, fmt.Errorf("get registration: %w", err)
	}
	return validateRecord(record, storedName, storedVersion)
}

func (r *Registry) GetByDigest(ctx context.Context, digest string) (Record, error) {
	if !validDigest.MatchString(digest) {
		return Record{}, ErrInvalidArgument
	}
	var record Record
	var storedName, storedVersion string
	err := r.pool.QueryRow(ctx, `SELECT
			agent_name,agent_version,manifest_digest,canonical_manifest,registered_at
		FROM agent_registrations WHERE manifest_digest=$1`,
		digest,
	).Scan(
		&storedName, &storedVersion, &record.Digest,
		&record.CanonicalJSON, &record.RegisteredAt,
	)
	if errors.Is(err, pgx.ErrNoRows) {
		return Record{}, ErrNotFound
	}
	if err != nil {
		return Record{}, fmt.Errorf("get registration by digest: %w", err)
	}
	return validateRecord(record, storedName, storedVersion)
}

func validateRecord(record Record, storedName, storedVersion string) (Record, error) {
	value, canonical, digest, err := manifest.Read(record.CanonicalJSON)
	if err != nil ||
		!bytes.Equal(canonical, record.CanonicalJSON) ||
		digest != record.Digest ||
		value.Agent.Name != storedName ||
		value.Agent.Version != storedVersion {
		return Record{}, ErrCorruptData
	}
	record.Manifest = value
	record.CanonicalJSON = append([]byte(nil), record.CanonicalJSON...)
	return record, nil
}
// Package manifest reads and verifies immutable agent manifests.
package manifest

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"regexp"
	"slices"
	"strings"

	"github.com/gowebpki/jcs"
)

var (
	lowerDigest = regexp.MustCompile(`^[0-9a-f]{64}$`)
	agentName   = regexp.MustCompile(`^[a-z][a-z0-9-]{0,62}$`)
	version     = regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+$`)
	label       = regexp.MustCompile(`^[a-z0-9][a-z0-9-]{0,62}$`)
)

var validStages = []string{"implementation", "planning", "review", "specification"}
var validCapabilities = []string{"general_reasoning", "independent_review", "strong_coding"}
var validTools = []string{
	"read_repository_file",
	"report_blocker",
	"request_declared_check",
	"search_repository",
}
var validOutputs = []string{
	"implementation_proposal.v1",
	"review_proposal.v1",
	"specification_proposal.v1",
	"task_graph_proposal.v1",
}
var stageOutputs = map[string]string{
	"specification":  "specification_proposal.v1",
	"planning":       "task_graph_proposal.v1",
	"implementation": "implementation_proposal.v1",
	"review":         "review_proposal.v1",
}

// Manifest is a transport-safe representation of agent-manifest v1.
type Manifest struct {
	SchemaVersion string   `json:"schema_version"`
	Agent         Agent    `json:"agent"`
	Stage         string   `json:"stage"`
	Prompt        Prompt   `json:"prompt"`
	Model         Model    `json:"model"`
	Context       Context  `json:"context"`
	Tools         Tools    `json:"tools"`
	Output        Output   `json:"output"`
	Metadata      Metadata `json:"metadata"`
}

type Agent struct {
	Name    string `json:"name"`
	Version string `json:"version"`
}

type Prompt struct {
	ArtifactURI string `json:"artifact_uri"`
	SHA256      string `json:"sha256"`
}

type Model struct {
	CapabilityClass     string  `json:"capability_class"`
	Temperature         float64 `json:"temperature"`
	MaximumOutputTokens int     `json:"maximum_output_tokens"`
}

type Context struct {
	IncludeSpecification bool   `json:"include_specification"`
	IncludeTask          bool   `json:"include_task"`
	RepositorySelection  string `json:"repository_selection"`
	MaximumContextTokens int    `json:"maximum_context_tokens"`
}

type Tools struct {
	AllowedRequests  []string `json:"allowed_requests"`
	ArbitraryShell   bool     `json:"arbitrary_shell"`
	ArbitraryNetwork bool     `json:"arbitrary_network"`
	DirectFileWrite  bool     `json:"direct_file_write"`
}

type Output struct {
	Schema string `json:"schema"`
}

type Metadata struct {
	Description string   `json:"description"`
	Labels      []string `json:"labels"`
}

// Read validates a closed manifest, canonicalizes it with RFC 8785, and returns
// its lowercase SHA-256 digest.
func Read(data []byte) (Manifest, []byte, string, error) {
	if err := validateRequiredFields(data); err != nil {
		return Manifest{}, nil, "", err
	}
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	var value Manifest
	if err := decoder.Decode(&value); err != nil {
		return Manifest{}, nil, "", fmt.Errorf("decode manifest: %w", err)
	}
	if err := requireEOF(decoder); err != nil {
		return Manifest{}, nil, "", err
	}
	if err := value.Validate(); err != nil {
		return Manifest{}, nil, "", err
	}
	canonical, err := jcs.Transform(data)
	if err != nil {
		return Manifest{}, nil, "", fmt.Errorf("canonicalize manifest: %w", err)
	}
	sum := sha256.Sum256(canonical)
	return value, canonical, hex.EncodeToString(sum[:]), nil
}

func validateRequiredFields(data []byte) error {
	var root map[string]json.RawMessage
	if err := json.Unmarshal(data, &root); err != nil {
		return fmt.Errorf("decode manifest: %w", err)
	}
	required := map[string][]string{
		"":         {"schema_version", "agent", "stage", "prompt", "model", "context", "tools", "output", "metadata"},
		"agent":    {"name", "version"},
		"prompt":   {"artifact_uri", "sha256"},
		"model":    {"capability_class", "temperature", "maximum_output_tokens"},
		"context":  {"include_specification", "include_task", "repository_selection", "maximum_context_tokens"},
		"tools":    {"allowed_requests", "arbitrary_shell", "arbitrary_network", "direct_file_write"},
		"output":   {"schema"},
		"metadata": {"description", "labels"},
	}
	if err := requireKeys("manifest", root, required[""]); err != nil {
		return err
	}
	for field, keys := range required {
		if field == "" {
			continue
		}
		var object map[string]json.RawMessage
		if err := json.Unmarshal(root[field], &object); err != nil {
			return fmt.Errorf("%s must be an object: %w", field, err)
		}
		if err := requireKeys(field, object, keys); err != nil {
			return err
		}
	}
	return nil
}

func requireKeys(name string, object map[string]json.RawMessage, keys []string) error {
	for _, key := range keys {
		if _, exists := object[key]; !exists {
			return fmt.Errorf("%s missing required field %s", name, key)
		}
	}
	return nil
}

func requireEOF(decoder *json.Decoder) error {
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return errors.New("decode manifest: trailing JSON value")
		}
		return fmt.Errorf("decode manifest: %w", err)
	}
	return nil
}

// Validate enforces the closed v1 policy without registry or persistence behavior.
func (m Manifest) Validate() error {
	if m.SchemaVersion != "1" {
		return errors.New("schema_version must be 1")
	}
	if err := validateAgent(m.Agent); err != nil {
		return err
	}
	if !slices.Contains(validStages, m.Stage) {
		return errors.New("unsupported stage")
	}
	if err := validatePrompt(m.Prompt); err != nil {
		return err
	}
	if err := validateModel(m.Model); err != nil {
		return err
	}
	if err := validateContext(m.Context); err != nil {
		return err
	}
	if err := validateTools(m.Tools); err != nil {
		return err
	}
	if !slices.Contains(validOutputs, m.Output.Schema) {
		return errors.New("unsupported output schema")
	}
	if m.Output.Schema != stageOutputs[m.Stage] {
		return errors.New("output schema does not match stage")
	}
	if len(m.Metadata.Description) > 500 || !sortedUniqueLabels(m.Metadata.Labels) {
		return errors.New("invalid metadata")
	}
	return nil
}

func validateAgent(agent Agent) error {
	if !agentName.MatchString(agent.Name) || !version.MatchString(agent.Version) {
		return errors.New("invalid agent name or version")
	}
	return nil
}

func validatePrompt(prompt Prompt) error {
	if !lowerDigest.MatchString(prompt.SHA256) ||
		prompt.ArtifactURI != "artifact://sha256/"+prompt.SHA256 {
		return errors.New("invalid prompt artifact URI or digest")
	}
	return nil
}

func validateModel(model Model) error {
	if !slices.Contains(validCapabilities, model.CapabilityClass) ||
		math.IsNaN(model.Temperature) || math.IsInf(model.Temperature, 0) ||
		model.Temperature < 0 || model.Temperature > 2 ||
		model.MaximumOutputTokens < 1 || model.MaximumOutputTokens > 200_000 {
		return errors.New("invalid model policy")
	}
	return nil
}

func validateContext(context Context) error {
	if context.RepositorySelection != "kernel_selected" ||
		context.MaximumContextTokens < 1 || context.MaximumContextTokens > 1_000_000 {
		return errors.New("invalid context policy")
	}
	return nil
}

func validateTools(tools Tools) error {
	if tools.ArbitraryShell || tools.ArbitraryNetwork || tools.DirectFileWrite {
		return errors.New("unsafe tool permission")
	}
	if !sortedUniqueSubset(tools.AllowedRequests, validTools) {
		return errors.New("invalid tool requests")
	}
	return nil
}

func sortedUniqueSubset(values, allowed []string) bool {
	if !slices.IsSorted(values) {
		return false
	}
