	}
	if _, err := pool.Exec(t.Context(), `DELETE FROM reasoning_invocations
		WHERE request_id=$1`, request.GetEnvelope().GetRequestId(),
	); err == nil {
		t.Fatal("completed invocation delete succeeded")
	}
}

